// Writes src/server/jobs/job-bundle.generated.ts: the files the Nebius batch job runs, as strings keyed by their path under the
// job work dir (/opt/le), so the Worker can inject them into the job container (`buildLocalEditionJob`, each file at most 64 KiB).
// It also writes `JOB_PACK_B64`: the same files as one gzipped JSON object (path -> text), base64. Nebius refuses a create request
// whose injected files total more than 64 KiB ("plaintext must not exceed 65536 bytes"; seen 30 Oct 2026, base64 counted), and
// the loose files plus the hashed requirements are over that, so the Worker injects the pack and run.sh unpacks it.
// Run `npm run gen:job-bundle` after changing jobs/ or guardrails/localedition/; a test fails when this file is stale.
import { readFileSync, writeFileSync } from "node:fs";
import { gzipSync } from "node:zlib";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const RAILS = ["actions.py", "batch.py", "catalogue.py", "injection.py", "rail_info.py", "config.yml", "prompts.yml", "rails.co"];

/** path under the job work dir -> source path, relative to the app root. */
export const SOURCES = {
  "certify.py": "jobs/certify.py",
  "le_http.py": "jobs/le_http.py",
  "requirements.txt": "jobs/requirements.txt",
  "rails/phrases.json": "guardrails/tests/phrases.json",
  ...Object.fromEntries(RAILS.map((f) => [`rails/${f}`, `guardrails/localedition/${f}`])),
};

export function render() {
  const files = Object.fromEntries(
    Object.entries(SOURCES).map(([path, src]) => {
      const text = readFileSync(resolve(root, src), "utf8");
      if (Buffer.byteLength(text) > 65536) throw new Error(`${src} is over the 64 KiB injected-file limit.`);
      return [path, text];
    }),
  );
  const body = Object.entries(files).map(([path, text]) => `  ${JSON.stringify(path)}: ${JSON.stringify(text)},`).join("\n");
  const pack = gzipSync(Buffer.from(JSON.stringify(files), "utf8"), { level: 9 }).toString("base64");
  return `// GENERATED by scripts/gen-job-bundle.mjs from jobs/ and guardrails/localedition/. Do not edit; run \`npm run gen:job-bundle\`.\n/** Path under the job work dir -> file text, injected into the Nebius job. */\nexport const JOB_BUNDLE: Readonly<Record<string, string>> = {\n${body}\n};\n\n/** The same files as one gzipped JSON object (path -> text), base64: what is actually injected (see the generator). */\nexport const JOB_PACK_B64 = ${JSON.stringify(pack)};\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(resolve(root, "src/server/jobs/job-bundle.generated.ts"), render());
}
